import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ' && c != -1) {
                c = readByte();
            }
            if (c == -1) return -1;
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res;
        }
    }

    static class MinHeap {
        private long[] data;
        private int size;

        public MinHeap(int capacity) {
            data = new long[capacity + 1];
            size = 0;
        }

        public void push(long val) {
            data[++size] = val;
            int cur = size;
            while (cur > 1) {
                int parent = cur >> 1;
                if (data[parent] > data[cur]) {
                    long tmp = data[parent];
                    data[parent] = data[cur];
                    data[cur] = tmp;
                    cur = parent;
                } else {
                    break;
                }
            }
        }

        public long pop() {
            long min = data[1];
            long last = data[size--];
            if (size > 0) {
                data[1] = last;
                int cur = 1;
                while ((cur << 1) <= size) {
                    int child = cur << 1;
                    if (child + 1 <= size && data[child + 1] < data[child]) {
                        child++;
                    }
                    if (data[cur] > data[child]) {
                        long tmp = data[cur];
                        data[cur] = data[child];
                        data[child] = tmp;
                        cur = child;
                    } else {
                        break;
                    }
                }
            }
            return min;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n == -1) return;
        int m = scanner.nextInt();

        int[] t = new int[n];
        for (int i = 0; i < n; i++) {
            t[i] = scanner.nextInt();
        }

        int[] f = new int[m];
        for (int i = 0; i < m; i++) {
            f[i] = scanner.nextInt();
        }

        Arrays.sort(t);

        if (n <= m) {
            System.out.println(0);
            return;
        }

        int k = n - m;
        long[] c = new long[k];

        MinHeap heap = new MinHeap(m);
        int[] p = new int[m];
        for (int i = 0; i < m; i++) {
            p[i] = 1;
            long val = f[i];
            heap.push((val << 20) | i);
        }

        for (int i = 0; i < k; i++) {
            long top = heap.pop();
            long val = top >>> 20;
            int mech = (int) (top & 0xFFFFF);
            c[i] = val;

            p[mech]++;
            long nextVal = (long) p[mech] * f[mech];
            heap.push((nextVal << 20) | mech);
        }

        long totalWaitTime = 0;
        for (int i = 0; i < k; i++) {
            totalWaitTime += (long) t[k - 1 - i] * c[i];
        }

        System.out.println(totalWaitTime);
    }
}
